package com.intermarche.e2e.engine.fieldops;
import com.intermarche.backoffice.domain.shipping.*;import com.intermarche.backoffice.domain.executing.*;import com.intermarche.backoffice.domain.store.*;import com.intermarche.backoffice.domain.stock.*;import com.intermarche.backoffice.domain.util.DateTimeProvider;import io.quarkus.test.junit.QuarkusTest;import io.quarkus.narayana.jta.QuarkusTransaction;import io.restassured.response.Response;import org.junit.jupiter.api.Test;import java.util.*;import java.math.BigDecimal;import static org.junit.jupiter.api.Assertions.*;import static io.restassured.RestAssured.given;
@QuarkusTest @jakarta.enterprise.inject.Typed(DepartureWorkflowTest.class)
class DepartureWorkflowTest extends ParcelWorkflowTest {
 Response departure(String token,String path,Object body){var r=given().auth().oauth2(token).contentType("application/json").body(body).post("/departures"+path);if(r.statusCode()>=400)System.out.println(path+" "+r.asString());return r;}
 Long buffer(){return QuarkusTransaction.requiringNew().call(()->{var b=new Buffer();b.building=Building.findById(f.building());b.bufferCode="DEP-BUF-"+key().substring(0,8);b.active=true;b.ambientCapacity=20;b.chilledCapacity=20;b.frozenCapacity=20;b.persistAndFlush();PickedItem.<PickedItem>findById(f.item()).loadedTote.buffer=b;return b.id;});}
 Map<String,Object> closedParcel(int quantity){var p=save(prepared(),quantity);var close=input(p);close.put("contentsConfirmed",true);return parcel(f.picker(),"/close",close).then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> draft(List<Map<String,Object>> units){return departure(f.picker(),"",Map.of("storeId",f.store(),"orderId",customer,"mode","CARRIER","recipient","Client test","transportReference","CAMION-TEST-1","units",units,"requestKey",key())).then().statusCode(200).extract().jsonPath().getMap("$");}
 Map<String,Object> inputDeparture(Map<String,Object> d){return new LinkedHashMap<>(Map.of("storeId",f.store(),"departureId",d.get("id"),"expectedRevision",d.get("revision"),"scannedDestination",d.get("destinationCode"),"requestKey",key()));}
 Map<String,Object> load(Map<String,Object> d,int index){var unit=((List<Map<String,Object>>)d.get("units")).get(index);var input=inputDeparture(d);input.put("unitId",unit.get("id"));input.put("scannedUnit",unit.get("code"));return departure(f.picker(),"/load",input).then().statusCode(200).extract().jsonPath().getMap("$");}
 void physicalTotal(int expected){QuarkusTransaction.requiringNew().run(()->eq(expected,stocks.availability(physical.account(),null,DateTimeProvider.now()).physical));}
 @Test void partialParcelLoadingKeepsRemainderInTheToteAndOnlyHandoverDecrementsStock(){var p=closedParcel(1);buffer();long tote=QuarkusTransaction.requiringNew().call(()->PickedItem.<PickedItem>findById(f.item()).loadedTote.id);given().auth().oauth2(f.picker()).get("/departures/choices?storeId="+f.store()+"&orderId="+customer).then().statusCode(200);var d=draft(List.of(Map.of("parcelId",p.get("id")),Map.of("toteId",tote)));var wrong=inputDeparture(d);wrong.put("unitId",((List<Map<String,Object>>)d.get("units")).getFirst().get("id"));wrong.put("scannedUnit",p.get("code"));wrong.put("scannedDestination","WRONG");departure(f.picker(),"/load",wrong).then().statusCode(400);d=load(d,0);physicalTotal(20);QuarkusTransaction.requiringNew().run(()->{eq(1,PickedItem.<PickedItem>findById(f.item()).quantity);var pc=ParcelContent.<ParcelContent>find("parcel.id",((Number)p.get("id")).longValue()).firstResult();assertNull(pc.pickedItem.loadedTote);eq(1,pc.quantity);assertTrue(Parcel.<Parcel>findById(((Number)p.get("id")).longValue()).materialized);eq(18,stocks.availability(physical.account(),null,DateTimeProvider.now()).eligiblePhysical);});var hand=inputDeparture(d);hand.put("recipient","Chauffeur test");hand.put("unitIds",List.of(((List<Map<String,Object>>)d.get("units")).getFirst().get("id")));d=departure(f.picker(),"/handover",hand).then().statusCode(200).body("state",org.hamcrest.Matchers.is("PARTIALLY_HANDED_OVER")).extract().jsonPath().getMap("$");departure(f.picker(),"/handover",hand).then().statusCode(200);physicalTotal(19);d=load(d,1);var second=inputDeparture(d);second.put("recipient","Chauffeur test");second.put("unitIds",List.of(((List<Map<String,Object>>)d.get("units")).get(1).get("id")));departure(f.picker(),"/handover",second).then().statusCode(200).body("state",org.hamcrest.Matchers.is("COMPLETED"));physicalTotal(18);QuarkusTransaction.requiringNew().run(()->{assertEquals("SHIPPED",com.intermarche.backoffice.domain.order.Order.<com.intermarche.backoffice.domain.order.Order>findById(customer).status);assertEquals(2,Shipment.count("store.id",f.store()));});}
 @Test void loadedRawToteCannotBeEditedAndCanBeExplicitlyUnloaded(){prepared();long b=buffer();long tote=QuarkusTransaction.requiringNew().call(()->PickedItem.<PickedItem>findById(f.item()).loadedTote.id);var d=load(draft(List.of(Map.of("toteId",tote))),0);attach(f.second());var move=command("MOVE_ITEM");move.putAll(Map.of("itemId",f.item(),"toteCode",f.tote(),"targetToteCode",f.second()));command(move).then().statusCode(409);physicalTotal(20);var unload=inputDeparture(d);var u=((List<Map<String,Object>>)d.get("units")).getFirst();unload.put("unitId",u.get("id"));unload.put("scannedUnit",u.get("code"));unload.put("bufferId",b);departure(f.picker(),"/unload",unload).then().statusCode(200);var retrieve=command("RETRIEVE_TOTE");retrieve.put("toteCode",f.tote());command(retrieve).then().statusCode(200);move.put("requestKey",key());command(move).then().statusCode(200);physicalTotal(20);}
 @Test void custodyOfferFreezesLoadingUntilTheNamedRecipientAccepts(){var p=closedParcel(2);var d=load(draft(List.of(Map.of("parcelId",p.get("id")))),0);var recipient=recipient();var offer=inputDeparture(d);offer.put("recipientEmployeeId",recipient.id());offer.put("reason","Relève du chargement");d=departure(f.picker(),"/custody",offer).then().statusCode(200).extract().jsonPath().getMap("$");var hand=inputDeparture(d);hand.put("recipient","Chauffeur");hand.put("unitIds",List.of(((List<Map<String,Object>>)d.get("units")).getFirst().get("id")));departure(f.picker(),"/handover",hand).then().statusCode(409);var accept=inputDeparture(d);accept.put("transferId",((List<Map<String,Object>>)d.get("transfers")).getFirst().get("id"));departure(f.picker(),"/custody/accept",accept).then().statusCode(403);d=departure(recipient.token(),"/custody/accept",accept).then().statusCode(200).extract().jsonPath().getMap("$");departure(recipient.token(),"/custody/accept",accept).then().statusCode(200);hand=inputDeparture(d);hand.put("recipient","Chauffeur");hand.put("unitIds",List.of(((List<Map<String,Object>>)d.get("units")).getFirst().get("id")));departure(f.picker(),"/handover",hand).then().statusCode(403);departure(recipient.token(),"/handover",hand).then().statusCode(200);physicalTotal(18);}
 @Test void recallAfterLoadingBlocksHandoverWithoutLosingTheLoadedParcel(){var p=closedParcel(2);var d=load(draft(List.of(Map.of("parcelId",p.get("id")))),0);quality(f.manager(),"POST","/cases",Map.of("storeId",f.store(),"productId",f.product(),"lotId",physical.second(),"kind","RECALL","reason","Rappel après chargement","requestKey",key(),"includeUnknownLots",true)).then().statusCode(200);var hand=inputDeparture(d);hand.put("recipient","Chauffeur");hand.put("unitIds",List.of(((List<Map<String,Object>>)d.get("units")).getFirst().get("id")));departure(f.picker(),"/handover",hand).then().statusCode(409);physicalTotal(20);given().auth().oauth2(f.manager()).get("/parcels/"+p.get("id")+"?storeId="+f.store()).then().statusCode(200).body("state",org.hamcrest.Matchers.is("LOADED"));}
 @Test void plannedCargoCannotBeReservedTwiceOrBypassedByTheDirectShippingShortcut(){prepared();buffer();long tote=QuarkusTransaction.requiringNew().call(()->PickedItem.<PickedItem>findById(f.item()).loadedTote.id);draft(List.of(Map.of("toteId",tote)));given().auth().oauth2(f.picker()).get("/shipments/orders?storeId="+f.store()).then().statusCode(200).body("[0].lines[0].totes[0].departureCode",org.hamcrest.Matchers.notNullValue());departure(f.picker(),"",Map.of("storeId",f.store(),"orderId",customer,"mode","CARRIER","recipient","Client test","transportReference","AUTRE-CAMION","units",List.of(Map.of("toteId",tote)),"requestKey",key())).then().statusCode(409);given().auth().oauth2(f.picker()).contentType("application/json").body(Map.of("storeId",f.store(),"orderId",customer,"mode","CARRIER","recipient","Client test","transportReference","RACCOURCI","toteIds",List.of(tote),"requestKey",key())).post("/shipments").then().statusCode(409);physicalTotal(20);}
}
